class CopilotSendTimeoutException(Exception):
    """Raised when writing one SSE frame to the client blocks for too long.

    Distinct from the stream-event timeout: that one bounds the agent, this one
    bounds the transport. A client that stops draining would otherwise wedge
    the handler and hold the connection open indefinitely.
    """

    pass


class InvalidCopilotSkillError(Exception):
    """Raised when a packaged Copilot skill directory is not a valid skill."""

    pass
